WFJ.Data.add("book", {
  ["f6048b46f10166f2"] = { "挨拶を送る、同胞よ。Shattered Handがよろしくと言っている。お前がValleyで腕を振るうのに心地よい場所だと思ってくれればとのことだ。これはお前にとって試練の時だ。常に見られていないなどと思うな。\n\nお前の技量をHandに報告し、より大きな試練に進む準備ができたと判断したら、それを彼らに伝えるのが私の務めだ。\n\n準備ができたら、Denの奥まで私を探しに来い。そこで待っている。\n\n-ローグのトレーナー、Rwag", "." },
  ["f63128548234a5fd"] = { "Dun Morogh一帯におけるFrostmane Trollsの状況に関する報告\n\nDun Moroghにいるトロールは、主に西の境にある山の洞窟、Frostmane Holdに集中している。いくらか懸念を抱かせるだけの数はいるが、彼らは自分たちの洞窟に留まっていることに十分満足しているようだ。これは間違いなく、再びドワーフの怒りを買って根絶やしにされる危険を冒したくないからである。彼らの行動は、強いて言えば縄張りを守るためのものと見なすことができ、そして", "." },
  ["f66b2d2e2f6a2600"] = { "ひどい窮地に陥ったものだと思わないか、{name}？Foul Princeに苦しめられ、愛する者たちからは疎まれ、はねつけられる。美しきSylvanasのおかげでようやく自分の意志を取り戻したが、それが今の我々に何をもたらすというのだ？主人が変わっても奴隷は奴隷だ、と私は思うがね。\n\nだが、もし我々のほうが主人だったら？そう、私の言いたいことは分かるだろう？\n\n我々はForsakenの仲間たちからさえ、なおいっそう隔てられているのだ、{name}。だからこそ、さらに話をせねばならない。Deathknellの教会で私を探してくれ。", "." },
  ["f66bf81ea0c85b84"] = { "gopherの散歩\n\nsnufflenose gopherは、狭くて暗い場所が好きです。そしてとても臆病です。\n\ngopherを散歩させたいなら、住処のように感じられる場所へ連れていかなければなりません。そして、gopherが大好物のblueleaf tubersの匂いを嗅げる場所へ、必ず連れていかなければなりません！\n\n最も近いそのような場所は、Razorfen Kraulの「溝」エリアです。溝の近くで箱を開け、gopherが近くの塊茎の匂いを嗅ぎつければ、gopherは外へ出てきてあなたの後をついていきます。", "." },
  ["f670b01919b9bf49"] = { "奴らは凍りついたように立ち尽くし、彼女は落ち着いてその視線を受け止めた。やがて騎手の一人が、遠くの呼び声を聞いたかのように顔を上げた。彼は衣の中から小さな宝石を取り出し、中を覗き込んだ。それからその飾り玉でSvenの妻を指し示した。光がそのRiderから女のほうへと這い寄り、不気味な白い手の形をとった。彼女はたじろがずにその光を見つめていたが、自信の仮面の奥に迷いがあるのが私には見えた。手が彼女に届くと、その指が彼女の頭の上に広がった。\n\nそして、握りしめた。", "." },
  ["f67b6ee200df28cb"] = { "よくやったな、相棒！ 次は真東へ向かうんだ。崖を上って東へ、道まで東へ。道端にある古い煙突の廃墟を探せ。そこにある古い樽に、次の手がかりがあるぜ。", "." },
  ["f698bcaa544d6c48"] = { "私が納屋に来て数日後、Svenは農場を出てDarkshireへ向かった。妻に口づけし、子供たちに微笑みかけ、おもちゃとお菓子を持ってすぐに帰ると約束した。哀れな男だ。それが、無残な姿になる前の家族を彼が見た最後だった。\n\nせめて、別れは幸せなものだった。せめて、妻が最初に死に、子供たちが殺されるのを見ずに済んだ。だが、そんなささやかな慈悲も私には何の救いにもならない。私は起きたことを見てしまい、それはいつまでも私の夢に取り憑くだろう。", "." },
  ["f6c0b889b9341d5b"] = { "血石のペンダントの近くにこぼれた血が、まるで重力が血石のほうへ曲げられたかのように、ゆっくりとその装身具のほうへ動いていたのである。ペンダントに触れた血は消えていくようで、私の血を吸うにつれて、石の赤色は深みを増していった。", "." },
  ["f6eb77f59ccb73af"] = { "Osricへ\n\n私どもが必要としている防具の一覧を以下にお送りします。\n\n10 Mailのシャツ\n20 Helms\n30 Armor Patches\n15 Mail Boots\n\nいつもながら、あなたには恩を感じております。そしてもしWestfallがそれを脅かす盗賊どもから解放される日が来たなら、かつてこの地がその名を馳せた実りで作った上等な料理で、あなたを我が家にお招きできれば、私の心の咎めも少しは和らぐことでしょう。\n\n-Lewis\nSentinel Hill、補給係", "." },
  ["f6f07033eafaeac7"] = { "Staghelmが後に悔やむことになる決断によって、若きStaghelm、Valstannは、ナイトエルフの前哨地Southwind Villageの防衛を命じられた。無念にも、Southwind VillageがAhn'Qirajの軍勢の手に落ちたその日、Valstannは命を落とした。", "." },
})
